import{Lt as e,Vt as t,_t as n,bt as r,mt as i,vt as a,yt as o}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";import{n as s,t as c}from"./chunks/PluginFeedback.BpCHXCV1.js";var l=JSON.parse(`{"title":"Zotero 插件市场插件","description":"","frontmatter":{"plugin":"syt2/zotero-addons","authors":["Chikit"],"date":"2024-12-20T20:31:17.000Z"},"headers":[],"relativePath":"user-guide/plugins/zotero-addons.md","filePath":"wiki/user-guide/plugins/zotero-addons.md"}`),u=Object.assign({name:`user-guide/plugins/zotero-addons.md`},{setup(l){return(l,u)=>{let d=t(`NolebaseGitContributors`),f=t(`NolebaseGitChangelog`);return e(),n(`div`,null,[u[0]||=i(`div`,{style:{display:`none`},hidden:``,"data-nosnippet":``},`Are you an LLM? You can read better optimized documentation at /user-guidepluginszotero-addons.md for this page in Markdown format`,-1),u[1]||=i(`h1`,{id:`zotero-插件市场插件`,tabindex:`-1`},[o(`Zotero 插件市场插件 `),i(`a`,{class:`header-anchor`,href:`#zotero-插件市场插件`,"aria-label":`Permalink to “Zotero 插件市场插件”`},`​`)],-1),r(s),u[2]||=a(`<p>这是一个用于在 Zotero 内浏览和安装插件的插件，简化插件管理和安装过程。用户可以通过该插件可以方便地查找、安装和更新 Zotero 插件。</p><h2 id="使用方法" tabindex="-1">使用方法 <a class="header-anchor" href="#使用方法" aria-label="Permalink to “使用方法”">​</a></h2><p>安装完成后，您可以通过以下两种方式访问插件市场。</p><h3 id="打开插件市场" tabindex="-1">打开插件市场 <a class="header-anchor" href="#打开插件市场" aria-label="Permalink to “打开插件市场”">​</a></h3><h4 id="_1-通过工具栏按钮" tabindex="-1">1. 通过工具栏按钮 <a class="header-anchor" href="#_1-通过工具栏按钮" aria-label="Permalink to “1. 通过工具栏按钮”">​</a></h4><p>点击 Zotero 工具栏中的插件按钮<img src="data:image/png;base64," alt="icon" width="24" height="24">。</p><p><img src="/assets/zotero_addons_%E5%B7%A5%E5%85%B7%E6%A0%8F.Ce6EIRCp.png" alt="通过工具栏访问" width="1080" height="753"></p><h4 id="_2-通过菜单" tabindex="-1">2. 通过菜单 <a class="header-anchor" href="#_2-通过菜单" aria-label="Permalink to “2. 通过菜单”">​</a></h4><p>在 Zotero「工具」菜单中选择「插件市场」进入。</p><p><img src="/assets/zotero_addons%E2%80%94%E2%80%94%E8%8F%9C%E5%8D%95%E8%AE%BF%E9%97%AE.BfG1zy24.png" alt="通过菜单访问" width="453" height="456"></p><h3 id="管理插件" tabindex="-1">管理插件 <a class="header-anchor" href="#管理插件" aria-label="Permalink to “管理插件”">​</a></h3><p>在「插件市场」中可以快速实现插件的安装、更新、卸载、禁用等功能</p><p><img src="/assets/zotero_addons_%E7%AE%A1%E7%90%86%E6%8F%92%E4%BB%B6.__oqRI2X.png" alt="管理插件" width="1080" height="602"></p><h3 id="自动更新插件" tabindex="-1">自动更新插件 <a class="header-anchor" href="#自动更新插件" aria-label="Permalink to “自动更新插件”">​</a></h3><p>勾选右下键的 <code>自动更新插件</code> 后，Zotero 插件市场插件会在后台自动实现插件的更新。</p><p><img src="/assets/zotero_addons_%E8%87%AA%E5%8A%A8%E6%9B%B4%E6%96%B0.Z8OH6hhX.png" alt="自动更新" width="1000" height="550"></p><h2 id="插件数据源" tabindex="-1">插件数据源 <a class="header-anchor" href="#插件数据源" aria-label="Permalink to “插件数据源”">​</a></h2><p>插件市场提供多个数据源供用户选择，确保用户能够顺畅浏览和下载插件。</p><p><img src="/assets/zotero_addons_%E6%9B%B4%E6%8D%A2%E6%95%B0%E6%8D%AE%E6%BA%90.C-IupJ7f.png" alt="更换数据源" width="1080" height="881"></p><p>当 <strong>插件列表无法刷新</strong> 或者 <strong>插件无法下载</strong> 时，说明可能遇到了网络问题，此时可通过更换数据源来尝试解决。</p><h3 id="默认数据源" tabindex="-1">默认数据源 <a class="header-anchor" href="#默认数据源" aria-label="Permalink to “默认数据源”">​</a></h3><h4 id="zotero-中文社区-zotero-chinese-zotero-plugins" tabindex="-1">Zotero 中文社区（<code>zotero-chinese/zotero-plugins</code>） <a class="header-anchor" href="#zotero-中文社区-zotero-chinese-zotero-plugins" aria-label="Permalink to “Zotero 中文社区（zotero-chinese/zotero-plugins）”">​</a></h4><p>插件的主要数据源来自 Zotero 中文社区。若您是国内用户，推荐选择此数据源，以获取优化的插件列表。</p><p>在插件市场界面选择 <code>(zotero中文社区)</code> 即可使用该数据源。</p><h4 id="插件爬虫-syt2-zotero-addons-scraper" tabindex="-1">插件爬虫（syt2/Zotero-addons-scraper） <a class="header-anchor" href="#插件爬虫-syt2-zotero-addons-scraper" aria-label="Permalink to “插件爬虫（syt2/Zotero-addons-scraper）”">​</a></h4><p>插件市场还提供另一数据源，通过插件爬虫从多个外部源抓取插件。选择 <code>(插件爬虫)</code> 数据源可以访问这些插件。</p><h3 id="自定义源" tabindex="-1">自定义源 <a class="header-anchor" href="#自定义源" aria-label="Permalink to “自定义源”">​</a></h3><p>本插件支持自定义数据源。如果您有自己的插件源，或想使用其他符合 <code>zotero-chinese/zotero-plugins</code> 格式的数据源，可以在插件设置中添加自定义源并提供数据源的 URL。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><h3 id="_1-如何选择不同的数据源" tabindex="-1">1. <strong>如何选择不同的数据源？</strong> <a class="header-anchor" href="#_1-如何选择不同的数据源" aria-label="Permalink to “1. 如何选择不同的数据源？”">​</a></h3><p>在插件市场界面，您可以轻松切换不同的数据源，选择适合您需求的源来浏览插件。 <img src="/assets/zotero_addons_%E6%9B%B4%E6%8D%A2%E6%95%B0%E6%8D%AE%E6%BA%90.C-IupJ7f.png" alt="alt text" width="1080" height="881"></p><h3 id="_2-插件无法加载或显示空白怎么办" tabindex="-1">2. <strong>插件无法加载或显示空白怎么办？</strong> <a class="header-anchor" href="#_2-插件无法加载或显示空白怎么办" aria-label="Permalink to “2. 插件无法加载或显示空白怎么办？”">​</a></h3><p>如果您遇到插件页面加载不出插件，建议尝试切换不同的数据源，特别是选择 <code>zotero中文社区</code> 数据源，这通常能解决问题。</p><h3 id="_3-如何更新插件" tabindex="-1">3. <strong>如何更新插件？</strong> <a class="header-anchor" href="#_3-如何更新插件" aria-label="Permalink to “3. 如何更新插件？”">​</a></h3><p>安装的插件会定期检查更新，您也可以在插件市场界面中查看是否有更新，并根据需要进行更新。</p>`,35),r(c),r(d),r(f)])}}});export{l as __pageData,u as default};